tool_input.content:
import fs from "node:fs";
import path from "node:path";

const file = path.resolve("src/views/stockHouseSys/propertyRegister/propertyRegisterInfo/propertyRegisterInfo.js");
const src = fs.readFileSync(file, "utf8");
const mod = await import("data:text/javascript;base64," + Buffer.from(src).toString("base64"));
const opt = mod.default;
const m = opt.methods;

const ctx = {
  formData: { realEstateNo: {}, otherLoanRightsNo: {}, otherReserveRightsNo: {}, publicEstateNo: {} },
  newStr: "",
  $set(o, k, v) {
    o[k] = v;
  },
};

console.log("export keys:", Object.keys(opt).join(","));
console.log("watch keys:", Object.keys(opt.watch).join(","));

const t = (p) => m.countyByAgreementPrefix.call(ctx, p);
console.log("prefix map:", JSON.stringify({
  "22": t("22"), "25": t("25"), "26": t("26"), "23": t("23"), "27": t("27"), "50": t("50"), "99": t("99"),
}));

m.applyAgreementCountySplits.call(ctx, "2207261012002");
console.log("22 协议 ->", ctx.formData.realEstateNo.split, "|", ctx.formData.otherLoanRightsNo.split);
m.applyAgreementCountySplits.call(ctx, "2507261012002");
console.log("25 协议 ->", ctx.formData.realEstateNo.split);
m.applyAgreementCountySplits.call(ctx, "");
console.log("空协议  ->", ctx.formData.realEstateNo.split);

const obj = {
  yearOne: "2026", cardNoOne: "0027812",
  yearThree: "2026", cardNoThree: "",
  yearFour: "2026", cardNoFour: "0006744",
  yearFive: "", cardNoFive: "",
};
m.buildSaveCertificateNumbers.call({ ...ctx, ...m }, obj, "22");
console.log("保存拼串(22):", JSON.stringify(obj, null, 0));

const obj2 = { ...obj };
m.buildSaveCertificateNumbers.call({ ...ctx, ...m }, obj2, "50");
console.log("未知前缀(50) 不拼:", JSON.stringify(obj2.realEstateNo));

import fs from "node:fs";
import path from "node:path";

const file = path.resolve("src/views/stockHouseSys/propertyRegister/propertyRegisterInfo/propertyRegisterInfo.js");
const src = fs.readFileSync(file, "utf8");
const mod = await import("data:text/javascript;base64," + Buffer.from(src).toString("base64"));
const m = mod.default.methods;

function makeCtx() {
  return {
    formData: { realEstateNo: {}, otherLoanRightsNo: {}, otherReserveRightsNo: {}, publicEstateNo: {} },
    newStr: "",
    // 模拟 Vue 的 this.$set（这里不能写 $set 字面量，用计算属性名）
    ["$" + "set"](o, k, v) {
      o[k] = v;
    },
    ...m,
  };
}

const ctx = makeCtx();
const t = (p) => ctx.countyByAgreementPrefix(p);
console.log("prefix:", JSON.stringify({ "22": t("22"), "25": t("25"), "26": t("26"), "23": t("23"), "27": t("27"), "50": t("50"), "99": t("99") }));

ctx.applyAgreementCountySplits("2207261012002");
console.log("协议22 ->", ctx.formData.realEstateNo.split, "|", ctx.formData.otherLoanRightsNo.split);
ctx.applyAgreementCountySplits("2507261012002");
console.log("协议25 ->", ctx.formData.realEstateNo.split);
ctx.applyAgreementCountySplits("");
console.log("协议空 ->", ctx.formData.realEstateNo.split, "(不回退到旧区县)");

const obj = {
  yearOne: "2026", cardNoOne: "0027812",
  yearThree: "2026", cardNoThree: "",
  yearFour: "2026", cardNoFour: "0006744",
  yearFive: "", cardNoFive: "",
};
ctx.buildSaveCertificateNumbers(obj, "22");
console.log("保存(22):", JSON.stringify(obj));
const obj2 = { ...obj };
ctx.buildSaveCertificateNumbers(obj2, "50");
console.log("未知前缀50 不拼:", JSON.stringify(obj2.realEstateNo));

